**Causas comuns de leak em Go:**

```go
// 1. Goroutines sem quit channel
func leakyWorker() {
    for {
        work := <-queue  // Bloqueia forever se queue não fechada
        process(work)
    }
}

// CORRETO:
func worker(ctx context.Context, queue chan Work) {
    for {
        select {
        case work := <-queue:
            process(work)
        case <-ctx.Done():
            return
        }
    }
}

// 2. Timer não parado
ticker := time.NewTicker(time.Second)  // Leak se não Stop()
defer ticker.Stop()

// 3. Slice append sem limit
var cache []Item
func add(item Item) {
    cache = append(cache, item)  // Cresce forever
}

// CORRETO: LRU ou limit
type Cache struct {
    items map[string]Item
    order list.List  // Para LRU
    max   int
}

// 4. HTTP body não fechado
resp, _ := http.Get(url)  // Leak se não Close
defer resp.Body.Close()

// 5. Mutex lock não released
mu.Lock()
if err != nil {
    return  // ESQUECEU: mu.Unlock()
}
mu.Unlock()

// CORRETO: defer
mu.Lock()
defer mu.Unlock()
```

