```

**6. Solução para o leak encontrado:**
```go
// ANTES (leak)
func processBatch(items []Item) {
    results := make([]Result, 0, len(items))
    for _, item := range items {
        results = append(results, heavyProcessing(item))
    }
    // results não é usado - GC não libera porque escopo mantém referência
}

// DEPOIS (corrigido)
func processBatch(items []Item) []Result {
    results := make([]Result, 0, len(items))
    for _, item := range items {
        results = append(results, heavyProcessing(item))
    }
    return results  // Usar ou retornar para GC liberar
}

// Ou limitar escopo:
func processBatch(items []Item) {
    func() {
        results := make([]Result, 0, len(items))
        for _, item := range items {
            results = append(results, heavyProcessing(item))
        }
        saveToDB(results)
    }()  // results liberado após função anônima
}
```

