instruction:
Analise este código C com undefined behavior: funciona em dev mas segfault em produção. Como debugar com Valgrind/ASan?
```c
#include <stdlib.h>
#include <string.h>

char* process_data(const char* input) {
    char buffer[256];
    strcpy(buffer, input);  // Buffer overflow se input > 256
    return strdup(buffer);
}

int main() {
    char* result = process_data("dados muito grandes...");
    free(result);
    return 0;
}
```

response:
**Análise do Undefined Behavior:**

**Problemas identificados:**
1. **Stack buffer overflow**: `strcpy` sem bounds checking
2. **UB (Undefined Behavior)**: Overflow de buffer é UB em C
3. **Por que funciona em dev**: Stack layout diferente, ASLR, input menor
4. **Segfault em produção**: Stack canary detectou corrupção ou overwrite de return address

**1. Detecção com AddressSanitizer (ASan):**
```bash
# Compilar com ASan
gcc -fsanitize=address -g -O0 program.c -o program

# Executar
./program

# Saída típica:
# ==12345==ERROR: AddressSanitizer: stack-buffer-overflow
# WRITE of size 300 at 0x7ffd12345678 thread T0
#     #0 0x5555555548a2 in process_data program.c:6
#     #1 0x5555555549c1 in main program.c:12
# 
# 0x7ffd12345678 is located 0 bytes to the right of stack buffer
# of size 256 in frame #0
```

**2. Valgrind para memcheck:**
```bash
# Executar com Valgrind
valgrind --tool=memcheck --leak-check=full --track-origins=yes ./program

# Saída típica:
# ==12345== Invalid write of size 1
# ==12345==    at 0x4C32E33: strcpy (vg_replace_strmem.c:...)
# ==12345==    by 0x1086A2: process_data (program.c:6)
# ==12345==    by 0x1089C1: main (program.c:12)
# ==12345==  Address 0x1ffefff000 is 0 bytes after a stack block of size 256
# ==12345==    in frame #1, created by main (program.c:10)
```

**3. Código corrigido:**
```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

char* process_data(const char* input) {
    // Solução 1: Verificar tamanho
    size_t len = strlen(input);
    if (len >= 256) {
        fprintf(stderr, "Input too long: %zu\n", len);
        return NULL;
    }

    char buffer[256];
    strncpy(buffer, input, 255);  // Seguro, mas não garante null-termination
    buffer[255] = '\0';  // Garantir null-termination
    return strdup(buffer);
}

// Solução 2: Heap allocation dinâmico (melhor)
char* process_data_dynamic(const char* input) {
    size_t len = strlen(input);
    char* buffer = malloc(len + 1);
    if (!buffer) {
        return NULL;
    }
    memcpy(buffer, input, len + 1);

    // Processamento...

    return buffer;  // Caller responsável por free
}

// Solução 3: asprintf (GNU extension)
#define _GNU_SOURCE
#include <stdio.h>

char* process_data_safe(const char* input) {
    char* result = NULL;
    if (asprintf(&result, "%s", input) < 0) {
        return NULL;
    }
    return result;
}

int main() {
    const char* large_input = "a";  // 1000 'a's

    char* result = process_data(large_input);
    if (result) {
        printf("Result: %s\n", result);
        free(result);
    } else {
        fprintf(stderr, "Error processing data\n");
        return 1;
    }

    return 0;
}
```

