**Diagnóstico de EventEmitter Leak em Node.js:**

**Sintomas:**
- Heap crescendo gradualmente
- EventEmitters acumulando listeners
- Warning: `(node) warning: possible EventEmitter memory leak detected`

**1. Coletar heap dumps:**
```bash
# Habilitar heap dump
npm install heapdump

# Código
const heapdump = require('heapdump');

// Trigger manual
heapdump.writeSnapshot('/var/log/heap-' + Date.now() + '.heapsnapshot');

# Ou automático quando heap > threshold
setInterval(() => {
  const heapUsed = process.memoryUsage().heapUsed;
  if (heapUsed > 500 * 1024 * 1024) {  // 500MB
    heapdump.writeSnapshot('/var/log/heap-' + Date.now() + '.heapsnapshot');
  }
}, 60000);
```

**2. Analisar no Chrome DevTools:**
```
1. Abrir chrome://inspect
2. Click 'Open dedicated DevTools for Node'
3. Memory tab → Load heap snapshot
4. Filtrar por 'EventEmitter' ou 'events.js'
5. Verificar 'Retained Size'

Exemplo de leak:
(events.js:EventEmitter) × 10000 instances = 50MB retained
```

**3. Código problemático típico:**

**A. Event listeners não removidos:**
```javascript
// ANTES (leak)
class OrderService {
  constructor(eventBus) {
    this.eventBus = eventBus;

    // Registra listener mas nunca remove!
    this.eventBus.on('order:created', this.handleOrder);
  }
}

// Cada instância adiciona listener, nunca remove
// 1000 instâncias = 1000 listeners

// DEPOIS (corrigido)
class OrderService {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.handleOrder = this.handleOrder.bind(this);
  }

  start() {
    this.eventBus.on('order:created', this.handleOrder);
  }

  stop() {
    // SEMPRE remover quando não precisar mais
    this.eventBus.removeListener('order:created', this.handleOrder);
  }
}

// Uso correto
const service = new OrderService(eventBus);
service.start();
// ... usar ...
service.stop();  // Cleanup obrigatório
```

**B. Closures capturando contexto grande:**
```javascript
// ANTES (leak por closure)
function setupHandler(server) {
  const hugeData = loadHugeConfig();  // 10MB

  server.on('request', (req, res) => {
    // Closure captura hugeData mesmo não usando!
    res.send('ok');
  });
}

// DEPOIS (não captura)
function setupHandler(server) {
  const hugeData = loadHugeConfig();

  server.on('request', createHandler(hugeData));
}

function createHandler(hugeData) {
  // Usa hugeData aqui se necessário
  return function handler(req, res) {
    // Não captura hugeData no closure
    res.send('ok');
  };
}
```

**C. Streams não fechadas:**
```javascript
// ANTES (leak)
app.get('/stream', (req, res) => {
  const stream = fs.createReadStream('huge-file.txt');
  stream.pipe(res);
  // Se cliente desconectar, stream continua aberta!
});

// DEPOIS (corrigido)
app.get('/stream', (req, res) => {
  const stream = fs.createReadStream('huge-file.txt');

  stream.pipe(res);

  // Cleanup quando resposta termina
  res.on('close', () => {
    stream.destroy();
  });

  stream.on('error', (err) => {
    console.error('Stream error:', err);
    res.destroy();
  });
});
```

**4. Monitoramento de EventEmitters:**
```javascript
// Wrapper para tracking
const EventEmitter = require('events');

const originalOn = EventEmitter.prototype.on;
const originalRemove = EventEmitter.prototype.removeListener;

// Tracking global
const listenerCounts = new Map();

EventEmitter.prototype.on = function(event, listener) {
  const key = `${this.constructor.name}:${event}`;
  listenerCounts.set(key, (listenerCounts.get(key) || 0) + 1);

  // Warning se muitos listeners
  if (listenerCounts.get(key) > 100) {
    console.warn(`Possible leak: ${key} has ${listenerCounts.get(key)} listeners`);
  }

  return originalOn.call(this, event, listener);
};

EventEmitter.prototype.removeListener = function(event, listener) {
  const key = `${this.constructor.name}:${event}`;
  listenerCounts.set(key, (listenerCounts.get(key) || 0) - 1);
  return originalRemove.call(this, event, listener);
};

// Export para métricas
setInterval(() => {
