**Análise de Race Condition em Contador:**

**Código problemático:**
```go
package main

import (
    "fmt"
    "sync"
)

type Counter struct {
    count int
}

func (c *Counter) Inc() {
    c.count++  // Não é atômico!
}

func main() {
    counter := &Counter{}
    var wg sync.WaitGroup

    for i := 0; i < 1000; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            counter.Inc()
        }()
    }

    wg.Wait()
    fmt.Println(counter.count)  // Esperado: 1000, Real: <1000
}
```

**Por que falha:**
```
Operação c.count++ não é atômica:

1. READ:  temp = c.count      (0)
2. ADD:   temp = temp + 1     (1)
3. WRITE: c.count = temp      (1)

Goroutine A    Goroutine B    Valor real
-----------    -----------    ----------
READ: 0        -              0
               READ: 0        0
ADD: 1         -              0
               ADD: 1         0
WRITE: 1       -              1
               WRITE: 1       1  ← Perdeu um incremento!

Resultado: 1 (esperado: 2)
Com 1000 goroutines: resultado aleatório < 1000
```

**Solução 1: sync/atomic (mais eficiente)**
```go
package main

import (
    "fmt"
    "sync"
    "sync/atomic"
)

type AtomicCounter struct {
    count int64  // Deve ser int64 para atomic
}

func (c *AtomicCounter) Inc() {
    atomic.AddInt64(&c.count, 1)
}

func (c *AtomicCounter) Get() int64 {
    return atomic.LoadInt64(&c.count)
}

func main() {
    counter := &AtomicCounter{}
    var wg sync.WaitGroup

    for i := 0; i < 1000; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            counter.Inc()
        }()
    }

    wg.Wait()
    fmt.Println(counter.Get())  // Sempre 1000
}
```

**Solução 2: sync.Mutex (mais flexível)**
```go
type MutexCounter struct {
    mu    sync.Mutex
    count int
}

func (c *MutexCounter) Inc() {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.count++
}

func (c *MutexCounter) Get() int {
    c.mu.Lock()
    defer c.mu.Unlock()
    return c.count
}

// RWMutex para leituras frequentes
type RWMutexCounter struct {
    mu     sync.RWMutex
    count  int
}

func (c *RWMutexCounter) Inc() {
    c.mu.Lock()
    c.count++
    c.mu.Unlock()
}

func (c *RWMutexCounter) Get() int {
    c.mu.RLock()
    defer c.mu.RUnlock()
    return c.count
}
```

**Solução 3: sync/atomic com compare-and-swap (CAS)**
```go
// Para operações mais complexas
type CASCounter struct {
    count int64
}

func (c *CASCounter) Inc() {
    for {
        old := atomic.LoadInt64(&c.count)
        new := old + 1

        // Tenta trocar old por new
        // Se count mudou desde o Load, falha e retry
        if atomic.CompareAndSwapInt64(&c.count, old, new) {
            return
        }
        // Retry se falhou (outra goroutine modificou)
    }
}

// CAS para update condicional
func (c *CASCounter) IncIfLessThan(max int64) bool {
    for {
        old := atomic.LoadInt64(&c.count)
        if old >= max {
            return false  // Não incrementa
        }

        new := old + 1
        if atomic.CompareAndSwapInt64(&c.count, old, new) {
            return true
        }
    }
}
```

**Solução 4: sync.Map (para mapas concorrentes)**
```go
// Se o contador é parte de um mapa
type MapCounter struct {
    counts sync.Map  // Thread-safe map
}

func (c *MapCounter) Inc(key string) {
    // Load ou store inicial
    actual, _ := c.counts.LoadOrStore(key, int64(0))

    // Loop até conseguir incrementar
    for {
        current := actual.(int64)
        if c.counts.CompareAndSwap(key, current, current+1) {
            return
        }
        // Recarrega se falhou
        actual, _ = c.counts.Load(key)
    }
}

func (c *MapCounter) Get(key string) int64 {
    val, ok := c.counts.Load(key)
    if !ok {
        return 0
    }
    return val.(int64)
}
```

